CREATE TABLE IF NOT EXISTS rate_limits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, rate_key VARCHAR(255) NOT NULL, action VARCHAR(100) NOT NULL, request_count INT NOT NULL DEFAULT 1, window_start DATETIME NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_rate_limit (rate_key, action)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
